17	package org.springframework.samples.petclinic.util;
18	
19	import java.nio.charset.StandardCharsets;
20	import java.security.MessageDigest;
21	import java.security.NoSuchAlgorithmException;
22	
23	/**
24	 * Derivation of an owner's {@code customerCode}, the region-and-hash identity every other owner value
25	 * is now built from. Kept separate from the owner controller and the {@code Owner} model so the rule
26	 * lives in one place, as pure functions with no web or persistence dependencies. Mirrors
27	 * {@link LocalityResolver} (which supplies the region) and {@link LuhnCheckDigit}.
28	 *
29	 * <p>The code is {@code '<REGION>-<HASH8>'}: REGION is the region derived from the owner's postcode
30	 * (see {@link LocalityResolver#resolveFromPostcode}) and HASH8 is the first eight upper-case
31	 * hexadecimal characters of the SHA-256 digest of the owner's normalized telephone concatenated with
32	 * the last name. It carries no sequence number, so two distinct people always receive distinct codes
33	 * only insofar as their {@code (telephone, lastName)} pairs differ.
34	 */
35	public abstract class CustomerCode {
36	
37	    /** Separates the region and hash components of the code. */
38	    private static final String SEPARATOR = "-";
39	
40	    /** Number of leading hex characters of the SHA-256 digest kept as the HASH8 component. */
41	    private static final int HASH_LENGTH = 8;
42	
43	    /**
44	     * Build a customer code {@code '<REGION>-<HASH8>'} from an owner's region, telephone and last name.
45	     *
46	     * @param region    the region code (e.g. {@code NSW}, or {@code UNKNOWN})
47	     * @param telephone the owner's normalized telephone, or null
48	     * @param lastName  the owner's last name, or null
49	     * @return the customer code
50	     */
51	    public static String of(String region, String telephone, String lastName) {
52	        return region + SEPARATOR + hash8(telephone, lastName);
53	    }
54	
55	    /**
56	     * The region (the part before the {@code '-'}) of a customer code, or {@code null} when the code is
57	     * {@code null}. This is how the owner's locality is now derived from its identity.
58	     *
59	     * @param customerCode a customer code, or null
60	     * @return the region component, or null
61	     */
62	    public static String region(String customerCode) {
63	        if (customerCode == null) {
64	            return null;
65	        }
66	        int separator = customerCode.indexOf(SEPARATOR);
67	        return separator < 0 ? customerCode : customerCode.substring(0, separator);
68	    }
69	
70	    /**
71	     * First eight upper-case hex characters of SHA-256 over {@code (telephone + lastName)}, each part
72	     * treated as the empty string when absent.
73	     */
74	    private static String hash8(String telephone, String lastName) {
75	        String telephonePart = telephone == null ? "" : telephone;
76	        String lastNamePart = lastName == null ? "" : lastName;
77	        return sha256Hex(telephonePart + lastNamePart).substring(0, HASH_LENGTH).toUpperCase();
78	    }
79	
80	    /** Full lower-case hex SHA-256 of the UTF-8 bytes of {@code value}. */
81	    private static String sha256Hex(String value) {
82	        try {
83	            byte[] digest = MessageDigest.getInstance("SHA-256")
84	                .digest(value.getBytes(StandardCharsets.UTF_8));
85	            StringBuilder hex = new StringBuilder(digest.length * 2);
86	            for (byte b : digest) {
87	                hex.append(String.format("%02x", b));
88	            }
89	            return hex.toString();
90	        }
91	        catch (NoSuchAlgorithmException e) {
92	            throw new IllegalStateException("SHA-256 is required but not available", e);
93	        }
94	    }
95	
96	}
