271	
272	    /**
273	     * Rejects an owner whose {@code firstName}, {@code lastName}, {@code address}, {@code city} or
274	     * {@code telephone} is missing (null) or blank (empty or whitespace only). Bean Validation on
275	     * the request body already rejects null and empty values, but permits whitespace-only strings
276	     * for fields without a stricter pattern (e.g. {@code city}, {@code address}); this guard closes
277	     * that gap so every required field must carry a non-blank value.
278	     *
279	     * @param ownerFieldsDto the submitted owner fields
280	     * @throws InvalidOwnerFieldsException if one or more required fields are missing or blank
281	     */
282	    private void rejectBlankOwnerFields(OwnerFieldsDto ownerFieldsDto) {
283	        List<String> missing = new ArrayList<>();
284	        addIfBlank(missing, "firstName", ownerFieldsDto.getFirstName());
285	        addIfBlank(missing, "lastName", ownerFieldsDto.getLastName());
286	        addIfBlank(missing, "address", ownerFieldsDto.getAddress());
287	        addIfBlank(missing, "city", ownerFieldsDto.getCity());
288	        addIfBlank(missing, "telephone", ownerFieldsDto.getTelephone());
289	        if (!missing.isEmpty()) {
290	            throw new InvalidOwnerFieldsException(missing);
291	        }
292	    }
293	
294	    /**
295	     * Rejects an owner whose supplied {@code postcode} is invalid for its {@code city}. The postcode is
296	     * optional: when absent (null) the owner is accepted unchanged, so the request contract stays
297	     * backward-compatible. When present it must be four digits and, when the city maps to a known region,
298	     * must fall within that region's fixed inclusive range ({@code NSW 2000-2099}, {@code VIC 3000-3099},
299	     * {@code QLD 4000-4099}); a city with no known region accepts any 4-digit postcode. See
300	     * {@link PostcodeValidator}.
301	     *
302	     * @param ownerFieldsDto the submitted owner fields (its {@code city} is non-blank here,
303	     *                       {@link #rejectBlankOwnerFields} having already run)
304	     * @throws InvalidOwnerFieldsException if a postcode is present but not valid for the city
305	     */
306	    private void rejectInvalidPostcode(OwnerFieldsDto ownerFieldsDto) {
307	        if (!PostcodeValidator.isValid(ownerFieldsDto.getCity(), ownerFieldsDto.getPostcode())) {
308	            throw new InvalidOwnerFieldsException(List.of("postcode"));
309	        }
310	    }
311	
312	    private void addIfBlank(List<String> missing, String fieldName, String value) {
313	        if (value == null || value.isBlank()) {
314	            missing.add(fieldName);
315	        }
316	    }
317	
318	    /**
319	     * Normalizes the submitted {@code address} on create to its canonical form (see
320	     * {@link AddressNormalizer#normalize}) and writes it back onto the request so it is the value
321	     * stored and returned, and the form every later address comparison (the required-field check,
322	     * household duplicate detection and the shared household id) is judged on. A null address is left
323	     * untouched so {@link #rejectBlankOwnerFields} still reports it as missing; a value that is blank
324	     * after normalization likewise reduces to the empty string and is rejected there.
325	     *
326	     * @param ownerFieldsDto the submitted owner fields
327	     */
328	    private void normalizeAddress(OwnerFieldsDto ownerFieldsDto) {
329	        String address = ownerFieldsDto.getAddress();
330	        if (address == null) {
331	            return;
332	        }
333	        ownerFieldsDto.setAddress(AddressNormalizer.normalize(address));
334	    }
335	
336	    /**
337	     * Normalizes the submitted {@code telephone} on create to its canonical form (see
338	     * {@link TelephoneNormalizer#normalize}) and writes it back onto the request so it is the value
339	     * stored and returned. Any input that does not reduce to a valid telephone is rejected with a
340	     * {@code 400 Bad Request}.
341	     *
342	     * @param ownerFieldsDto the submitted owner fields (its {@code telephone} is non-blank here,
343	     *                       {@link #rejectBlankOwnerFields} having already run)
344	     * @throws InvalidOwnerFieldsException if the telephone cannot be normalized to a valid value
345	     */
346	    private void normalizeTelephone(OwnerFieldsDto ownerFieldsDto) {
347	        String normalized = TelephoneNormalizer.normalize(ownerFieldsDto.getTelephone())
348	            .orElseThrow(() -> new InvalidOwnerFieldsException(List.of("telephone")));
349	        ownerFieldsDto.setTelephone(normalized);
350	    }
351	
352	    /**
353	     * Normalizes an optionally-supplied {@code email}. When absent (null) or blank the field is left
354	     * untouched (email is optional). When present it is reduced to its canonical form (see
355	     * {@link EmailNormalizer#normalize}) and written back so it is the value stored and returned. Any
356	     * present-but-invalid address is rejected with a {@code 400 Bad Request}.
357	     *
358	     * @param ownerFieldsDto the submitted owner fields
359	     * @throws InvalidOwnerFieldsException if the email is present but not a syntactically valid address,
360	     *                                     or its domain is on the disposable-domain blocklist
361	     */
362	    private void normalizeEmail(OwnerFieldsDto ownerFieldsDto) {
363	        String email = ownerFieldsDto.getEmail();
364	        if (email == null || email.isBlank()) {
365	            return;
366	        }
367	        String normalized = EmailNormalizer.normalize(email)
368	            .orElseThrow(() -> new InvalidOwnerFieldsException(List.of("email")));
369	        if (EmailNormalizer.hasDisposableDomain(normalized)) {
370	            throw new InvalidOwnerFieldsException(List.of("email"));
371	        }
372	        ownerFieldsDto.setEmail(normalized);
373	    }
374	
375	    /**
376	     * Rejects creating an owner whose derived identity collides with an existing owner. All owner
377	     * duplicate detection is now expressed through the single derived {@code identityKey}
378	     * ({@code normalizedTelephone + '|' + email + '|' + householdId}, see {@link OwnerIdentity}),
379	     * which replaces the previously separate telephone, email and household checks. Two owners denote
380	     * the same person when their identities collide on the telephone - the identity's distinguishing
381	     * component - so a create is rejected as a {@code 409 Conflict} when another owner already carries
382	     * the same normalized telephone. Because the telephone is part of the identity, two members of the
383	     * same household with different telephones have different identities and are both allowed; an email
384	     * or a household on its own no longer makes a duplicate.
385	     *
386	     * @param ownerFieldsDto the submitted owner fields, with telephone and email already normalized
387	     *                       ({@link #normalizeTelephone}, {@link #normalizeEmail})
388	     * @param householdId    the household id derived for the owner being created (see
389	     *                       {@link HouseholdNormalizer#toHouseholdId})
390	     * @throws DuplicateOwnerIdentityException if another owner already carries the same identity
391	     */
392	    private void rejectDuplicateIdentity(OwnerFieldsDto ownerFieldsDto, String householdId) {
393	        String identityKey = OwnerIdentity.identityKey(
394	            ownerFieldsDto.getTelephone(), ownerFieldsDto.getEmail(), householdId);
395	        String telephoneKey = TelephoneNormalizer.toComparisonKey(ownerFieldsDto.getTelephone());
396	        boolean inUse = this.clinicService.findAllOwners().stream()
397	            .map(Owner::getTelephone)
398	            .filter(Objects::nonNull)
399	            .map(TelephoneNormalizer::toComparisonKey)
400	            .anyMatch(telephoneKey::equals);
401	        if (inUse) {
402	            throw new DuplicateOwnerIdentityException(identityKey);
403	        }
404	    }
405	
406	    /**
407	     * Counts the existing owners (before this create) whose {@code firstName} and {@code lastName}
408	     * both match the submitted values, compared case-insensitively. The count reflects only owners
409	     * already persisted at the time of the create, so the owner being created is never included.
410	     *
411	     * @param firstName the submitted first name (non-blank here, {@link #rejectBlankOwnerFields}
412	     *                  having already run)
413	     * @param lastName  the submitted last name (non-blank here)
414	     * @return the number of existing owners sharing the same first and last name
415	     */
416	    private int countNamesakes(String firstName, String lastName) {
417	        return (int) this.clinicService.findAllOwners().stream()
418	            .filter(owner -> firstName.equalsIgnoreCase(owner.getFirstName())
419	                && lastName.equalsIgnoreCase(owner.getLastName()))
420	            .count();
421	    }
422	
423	    /**
424	     * Counts the existing owners (before this create) belonging to the given household, i.e. those
425	     * whose stored {@code householdId} equals the value derived for the owner being created. The
426	     * count reflects only owners already persisted at the time of the create, so the owner being
427	     * created is never included; callers add one to obtain the household size after this create.
428	     *
429	     * @param householdId the household identifier derived for the owner being created (see
430	     *                    {@link HouseholdNormalizer#toHouseholdId})
431	     * @return the number of existing owners already sharing that household
432	     */
433	    private int countHouseholdMembers(String householdId) {
434	        if (householdId == null) {
435	            return 0;
436	        }
437	        return (int) this.clinicService.findAllOwners().stream()
438	            .map(Owner::getHouseholdId)
439	            .filter(householdId::equals)
440	            .count();
441	    }
442	
443	    /**
444	     * Derives the household id an owner should carry from its submitted fields (see
445	     * {@link HouseholdNormalizer#toHouseholdId}). Both create and update stamp an owner with a
446	     * household id, so routing them through this single method keeps them agreed on which of the
447	     * owner's fields key the household.
448	     *
449	     * @param ownerFieldsDto the submitted owner fields (its identifying fields are non-blank here,
450	     *                       {@link #rejectBlankOwnerFields} having already run on create)
451	     * @return the owner's household id
452	     */
453	    private String householdIdFor(OwnerFieldsDto ownerFieldsDto) {
454	        return HouseholdNormalizer.toHouseholdId(
455	            ownerFieldsDto.getLastName(), ownerFieldsDto.getPostcode());
456	    }
457	
458	    /**
459	     * Rejects creating an owner that would join an existing household without declaring itself a
460	     * member. The household is keyed on (last name, postcode) through the derived {@code householdId}
461	     * (see {@link HouseholdNormalizer#toHouseholdId}), so a second owner sharing an existing owner's
462	     * last name and postcode denotes the same household. Such a create is reported as a {@code 409
463	     * Conflict} unless it opts in with {@code sharesHousehold}, in which case it is accepted as a
464	     * declared household member. Only owners already persisted (before this create) are considered.
465	     *
466	     * @param householdId     the household id derived for the owner being created
467	     * @param sharesHousehold whether the request opted in to sharing a household
468	     * @throws DuplicateOwnerHouseholdException if the household already exists and the request did not
469	     *                                          opt in with {@code sharesHousehold}
470	     */
471	    private void rejectHouseholdDuplicate(String householdId, boolean sharesHousehold) {
472	        if (sharesHousehold || householdId == null) {
473	            return;
474	        }
475	        boolean householdExists = this.clinicService.findAllOwners().stream()
476	            .map(Owner::getHouseholdId)
477	            .anyMatch(householdId::equals);
478	        if (householdExists) {
479	            throw new DuplicateOwnerHouseholdException(householdId);
480	        }
481	    }
482	
483	    /**
484	     * Finds an existing owner that the owner being created soft-matches on, or {@code null} when there
485	     * is none. The create has already cleared the hard-duplicate identity check
486	     * ({@link #rejectDuplicateIdentity}), so it is not an exact match of any existing owner; it is a
487	     * <em>possible</em> duplicate when it nevertheless shares an existing owner's {@code lastName}
488	     * (compared case-insensitively) and {@code postcode} while carrying a different normalized
489	     * telephone. The oldest such owner (the earliest persisted) is returned so the flag points at the
490	     * original record; owners with no postcode never match, since a shared postcode is required.
491	     *
492	     * @param owner the owner being created, with telephone already normalized and lastName/postcode set
493	     * @return the id of the matching existing owner, or {@code null} when the owner is not a possible
494	     *         duplicate
495	     */
496	    private Integer findPossibleDuplicate(Owner owner) {
497	        String postcode = owner.getPostcode();
498	        if (postcode == null) {
499	            return null;
500	        }
501	        String telephoneKey = TelephoneNormalizer.toComparisonKey(owner.getTelephone());
502	        return this.clinicService.findAllOwners().stream()
503	            .filter(existing -> owner.getLastName().equalsIgnoreCase(existing.getLastName()))
504	            .filter(existing -> postcode.equals(existing.getPostcode()))
505	            .filter(existing -> existing.getTelephone() != null
506	                && !telephoneKey.equals(TelephoneNormalizer.toComparisonKey(existing.getTelephone())))
507	            .map(Owner::getId)
508	            .filter(Objects::nonNull)
509	            .min(Integer::compareTo)
510	            .orElse(null);
511	    }
512	
513	    /**
514	     * Records on the owner being created whether it is a possible (soft) duplicate of an existing
515	     * owner. The match itself is decided by {@link #findPossibleDuplicate}; this method reflects its
516	     * result into the two stored fields, so the interpretation of "is a possible duplicate" lives in
517	     * one place: {@code possibleDuplicateOf} holds the matched owner's id (or {@code null} when there
518	     * is none) and {@code possibleDuplicate} is {@code true} exactly when a match was found. An owner
519	     * that opted in with {@code sharesHousehold} is a declared household member, not a suspected
520	     * duplicate, so it is never flagged.
521	     *
522	     * @param owner           the owner being created, with telephone already normalized and
523	     *                        lastName/postcode set
524	     * @param sharesHousehold whether the request opted in to sharing a household
525	     */
526	    private void markPossibleDuplicate(Owner owner, boolean sharesHousehold) {
527	        Integer possibleDuplicateOf = sharesHousehold ? null : findPossibleDuplicate(owner);
528	        owner.setPossibleDuplicate(possibleDuplicateOf != null);
529	        owner.setPossibleDuplicateOf(possibleDuplicateOf);
530	    }
531	
532	    /**
533	     * Rejects creating an owner whose city already holds {@link #MAX_OWNERS_PER_CITY} or more owners.
534	     * The submitted city is compared case-insensitively against every existing owner's stored city; a
535	     * city that is already at (or over) capacity is reported as a {@code 409 Conflict}.
536	     *
537	     * @param city the submitted city (non-blank here, {@link #rejectBlankOwnerFields} having already
538	     *             run)
539	     * @throws OwnerCityAtCapacityException if the city already contains the maximum number of owners
540	     */
541	    private void rejectCityAtCapacity(String city) {
542	        long ownersInCity = this.clinicService.findAllOwners().stream()
543	            .map(Owner::getCity)
544	            .filter(Objects::nonNull)
545	            .filter(city::equalsIgnoreCase)
546	            .count();
547	        if (ownersInCity >= MAX_OWNERS_PER_CITY) {
548	            throw new OwnerCityAtCapacityException(city);
549	        }
550	    }
551	
552	    /**
553	     * Resolves the effective registration date for a create, rolled onto a business day. The
554	     * supplied date is used when present, otherwise the server's current date; either way the result
555	     * is rolled forward to the next Monday when it falls on a Saturday or Sunday (see
556	     * {@link BusinessDayAdjuster#toBusinessDay}). Every value derived from the registration date - the
557	     * stored {@code registrationDate}, the membership number's year segment and the daily
558	     * create-limit's per-day count - is judged on this adjusted date.
559	     *
560	     * @param suppliedRegistrationDate the registration date from the request, or {@code null} to
561	     *                                 default to the server's current date
562	     * @return the effective registration date, guaranteed to fall on a business day
563	     */
564	    /**
565	     * Rejects a create whose supplied {@code registrationDate} lies after the server's current date.
566	     * The raw submitted value is compared against {@link LocalDate#now()} before any business-day
567	     * adjustment; a future date cannot describe a registration that has already happened, so it is
568	     * reported as a {@code 400 Bad Request}. A {@code null} registration date (defaulted to the
569	     * server's current date) and any date on or before today are accepted.
570	     *
571	     * @param suppliedRegistrationDate the registration date from the request, or {@code null} when
572	     *                                 omitted
573	     * @throws InvalidOwnerFieldsException if the supplied date is later than the server's current date
574	     */
575	    private void rejectFutureRegistrationDate(LocalDate suppliedRegistrationDate) {
576	        if (suppliedRegistrationDate != null && suppliedRegistrationDate.isAfter(LocalDate.now())) {
577	            throw new InvalidOwnerFieldsException(List.of("registrationDate"));
578	        }
579	    }
580	
581	    private LocalDate effectiveRegistrationDate(LocalDate suppliedRegistrationDate) {
582	        LocalDate registrationDate =
583	            suppliedRegistrationDate != null ? suppliedRegistrationDate : LocalDate.now();
584	        return BusinessDayAdjuster.toBusinessDay(registrationDate);
585	    }
586	
587	    /**
588	     * Rejects creating an owner once {@link #MAX_OWNERS_PER_DAY} or more owners have already been
589	     * created for the given business day, judged by their stored {@code registrationDate}. Only owners
590	     * already persisted (before this create) are counted, and only those whose {@code registrationDate}
591	     * equals the adjusted registration date; a day at (or over) that limit is reported as a {@code 429
592	     * Too Many Requests}.
593	     *
594	     * @param registrationDate   the create's effective registration date, already rolled onto a
595	     *                           business day by {@link #effectiveRegistrationDate}
596	     * @param registeredThatDay  the number of owners already persisted (before this create) whose
597	     *                           {@code registrationDate} equals {@code registrationDate}
598	     * @throws OwnerDailyRegistrationLimitException if that day has already reached the maximum number of
599	     *                                              owner registrations
600	     */
601	    private void rejectDailyRegistrationLimitReached(LocalDate registrationDate, long registeredThatDay) {
602	        if (registeredThatDay >= MAX_OWNERS_PER_DAY) {
603	            throw new OwnerDailyRegistrationLimitException(registrationDate);
604	        }
605	    }
606	
607	    /**
608	     * Counts the owners already persisted (before this create) whose stored {@code registrationDate}
609	     * equals the given day. This is the shared per-day accumulation both the daily create-limit and the
610	     * bulk-signup warning are judged on.
611	     *
612	     * @param registrationDate the create's effective registration date, already rolled onto a business
613	     *                         day by {@link #effectiveRegistrationDate}
614	     * @return the number of existing owners registered on that day
615	     */
616	    private long countRegisteredOn(LocalDate registrationDate) {
617	        return this.clinicService.findAllOwners().stream()
618	            .map(Owner::getRegistrationDate)
619	            .filter(registrationDate::equals)
620	            .count();
621	    }
622	}
